"use client"

import { revalidateLogic } from "@tanstack/react-form"
import { type ReactNode, useMemo } from "react"

import { Badge } from "@/components/ui/badge"
import { FieldGroup } from "@/components/ui/field"
import {
  FormDialog,
  FormDialogBody,
  FormDialogCancel,
  FormDialogDescription,
  FormDialogError,
  FormDialogFooter,
  FormDialogForm,
  FormDialogHeader,
  FormDialogSubmit,
  FormDialogTitle,
} from "@/components/openlmis/form-dialog/form-dialog"
import { useDialogTarget } from "@/components/openlmis/form-dialog/use-dialog-target"
import { useAppForm } from "@/components/openlmis/form-fields/form"
import {
  SwitchField,
  ChoiceCardSkeleton,
  ComboboxField,
  FieldSkeleton,
  SkeletonLine,
} from "@/components/openlmis/form-fields/form-fields"
import { Callout } from "@/components/openlmis/callout"
import { StatusBadge } from "@/components/openlmis/status-badge"

import {
  canNotify,
  EMPTY_USER_FORM,
  type Facility,
  statusMismatch,
  toSavedValues,
  toUserFormValues,
  type UserDetails,
  type UserFormValues,
  userFormSchema,
} from "@/components/openlmis/list-page/user-form"

/** `"new"` adds a user; an id edits that user. */
export type UserFormDialogTarget = "new" | (string & {})

type UserFormDialogProps = {
  /** Opens the dialog while set. */
  target: UserFormDialogTarget | undefined
  /** The user being edited; the form shows a skeleton until it is set. */
  user?: UserDetails | undefined
  /** The home facility choices; the field shows a skeleton until they are set. */
  facilities: readonly Facility[] | undefined
  /** Called with trimmed values; save them, then clear `target` to close. */
  onSubmit: (values: UserFormValues, existing?: UserDetails) => void
  /** Keeps the dialog open and shows a spinner while the save runs. */
  pending?: boolean
  /** Shown above the fields, e.g. why the save failed; what was typed stays. */
  error?: ReactNode
  onClose: () => void
}

export function UserFormDialog({
  target,
  user,
  facilities,
  onSubmit,
  pending = false,
  error,
  onClose,
}: UserFormDialogProps) {
  const { shown, dialogProps } = useDialogTarget(target, onClose)
  const form = { facilities, onSubmit, pending, error }

  return (
    <FormDialog {...dialogProps(pending)}>
      {shown === "new" && <UserForm {...form} />}
      {shown !== undefined &&
        shown !== "new" &&
        (user?.id === shown ? (
          // Keyed, so another user's values never carry over.
          <UserForm {...form} details={user} key={user.id} />
        ) : (
          <UserFormSkeleton />
        ))}
    </FormDialog>
  )
}

type UserFormProps = Pick<
  UserFormDialogProps,
  "facilities" | "onSubmit" | "error"
> & {
  pending: boolean
  details?: UserDetails
}

function UserForm({
  details,
  facilities,
  onSubmit,
  pending,
  error,
}: UserFormProps) {
  const isEdit = details !== undefined

  const form = useAppForm({
    defaultValues: details ? toUserFormValues(details) : EMPTY_USER_FORM,
    // Quiet until the first submit, then each field re-checks as it is corrected.
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: userFormSchema },
    onSubmit: ({ value }) => onSubmit(toSavedValues(value, details), details),
  })

  const savedEmail = details?.email ?? ""
  const homeFacilityRoles = details?.homeFacilityRoleCount ?? 0
  const savedFacilityId = details?.homeFacilityId ?? null
  const mismatch = details && statusMismatch(details)

  return (
    <FormDialogForm onSubmit={() => void form.handleSubmit()}>
      <FormDialogHeader>
        <FormDialogTitle>{isEdit ? "Edit User" : "Add User"}</FormDialogTitle>
        <FormDialogDescription>
          {isEdit
            ? `Details for ${details.username}.`
            : "Create an account that can sign in to OpenLMIS."}
        </FormDialogDescription>
      </FormDialogHeader>
      <FormDialogBody>
        <FieldGroup>
          {error && (
            <FormDialogError description={error} title="Could Not Save User" />
          )}

          <form.AppField name="username">
            {(field) => (
              <field.TextField
                autoComplete="off"
                dir="ltr"
                label="Username"
                required
              />
            )}
          </form.AppField>

          <FieldRow>
            <form.AppField name="firstName">
              {(field) => (
                <field.TextField
                  autoComplete="off"
                  label="First Name"
                  required
                />
              )}
            </form.AppField>
            <form.AppField name="lastName">
              {(field) => (
                <field.TextField
                  autoComplete="off"
                  label="Last Name"
                  required
                />
              )}
            </form.AppField>
          </FieldRow>

          <form.AppField
            listeners={{
              // Notifications go to the verified address, so a new one switches them off.
              onChange: ({ value }) => {
                if (isEdit && value.trim() !== savedEmail)
                  form.setFieldValue("allowNotify", false)
              },
            }}
            name="email"
          >
            {(field) => (
              <field.TextField
                autoComplete="off"
                description={
                  isEdit &&
                  savedEmail &&
                  field.state.value.trim() === savedEmail && (
                    <EmailStatus verified={details.emailVerified} />
                  )
                }
                dir="ltr"
                label="Email"
                type="email"
              />
            )}
          </form.AppField>

          <FieldRow>
            <form.AppField name="jobTitle">
              {(field) => (
                <field.TextField autoComplete="off" label="Job Title" />
              )}
            </form.AppField>
            <form.AppField name="phoneNumber">
              {(field) => (
                <field.TextField
                  autoComplete="off"
                  dir="ltr"
                  label="Phone Number"
                  type="tel"
                />
              )}
            </form.AppField>
          </FieldRow>

          <form.AppField name="homeFacilityId">
            {() => <HomeFacilityField facilities={facilities} />}
          </form.AppField>

          {homeFacilityRoles > 0 && (
            <form.Subscribe selector={(state) => state.values.homeFacilityId}>
              {(homeFacilityId) =>
                homeFacilityId !== savedFacilityId && (
                  <form.AppField name="removeHomeFacilityRoles">
                    {() => (
                      <SwitchField
                        description={`${homeFacilityRoles === 1 ? "1 role applies" : `${homeFacilityRoles} roles apply`} only at the current home facility.`}
                        label="Remove Home Facility Roles"
                      />
                    )}
                  </form.AppField>
                )
              }
            </form.Subscribe>
          )}

          {mismatch && (
            <Callout title="Status Does Not Match" tone="warning">
              {mismatch === "listed-inactive"
                ? `The Users list shows ${details.username} as inactive, but they can still sign in. Saving applies the Active switch below to both.`
                : `The Users list shows ${details.username} as active, but they cannot sign in. Saving applies the Active switch below to both.`}
            </Callout>
          )}

          <form.AppField name="active">
            {(field) => (
              <field.SwitchField
                description="Inactive users cannot sign in."
                label="Active"
              />
            )}
          </form.AppField>

          {isEdit && (
            <form.Subscribe
              selector={(state) =>
                canNotify(
                  state.values.email,
                  details.email,
                  details.emailVerified
                )
              }
            >
              {(verified) => (
                <form.AppField name="allowNotify">
                  {(field) => (
                    <field.SwitchField
                      description={
                        verified
                          ? "Send every notification this user's roles allow."
                          : "Available once the email address is verified."
                      }
                      disabled={!verified}
                      label="Allow Notifications"
                    />
                  )}
                </form.AppField>
              )}
            </form.Subscribe>
          )}
        </FieldGroup>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel disabled={pending} />
        <FormDialogSubmit pending={pending}>
          {isEdit ? "Save Changes" : "Create User"}
        </FormDialogSubmit>
      </FormDialogFooter>
    </FormDialogForm>
  )
}

function FieldRow({ children }: { children: ReactNode }) {
  return <div className="grid gap-5 sm:grid-cols-2">{children}</div>
}

function EmailStatus({ verified }: { verified: boolean }) {
  return verified ? (
    <StatusBadge tone="success">Verified</StatusBadge>
  ) : (
    <Badge variant="secondary">Not Verified</Badge>
  )
}

/** Reads its field from the surrounding `AppField`. */
function HomeFacilityField({
  facilities,
}: Pick<UserFormDialogProps, "facilities">) {
  const items = useMemo(
    () =>
      (facilities ?? []).map((facility) => ({
        value: facility.id,
        label: `${facility.code} - ${facility.name}`,
      })),
    [facilities]
  )

  if (!facilities) return <FieldSkeleton label="Home Facility" />
  return (
    <ComboboxField
      clearLabel="Clear Home Facility"
      emptyMessage="No facilities found."
      items={items}
      label="Home Facility"
      placeholder="Search Facilities..."
    />
  )
}

/** The edit form as it will look, laid out the same, so nothing moves when the user arrives. */
function UserFormSkeleton() {
  return (
    <>
      <FormDialogHeader>
        <FormDialogTitle>Edit User</FormDialogTitle>
        <SkeletonLine width="short" />
      </FormDialogHeader>
      <FormDialogBody>
        <div aria-busy>
          <FieldGroup>
            <FieldSkeleton label="Username" required />
            <FieldRow>
              <FieldSkeleton label="First Name" required />
              <FieldSkeleton label="Last Name" required />
            </FieldRow>
            <FieldSkeleton label="Email" />
            <FieldRow>
              <FieldSkeleton label="Job Title" />
              <FieldSkeleton label="Phone Number" />
            </FieldRow>
            <FieldSkeleton label="Home Facility" />
            <ChoiceCardSkeleton
              description="Inactive users cannot sign in."
              label="Active"
            />
            <ChoiceCardSkeleton label="Allow Notifications" />
          </FieldGroup>
        </div>
      </FormDialogBody>
      <FormDialogFooter>
        <FormDialogCancel />
        <FormDialogSubmit disabled>Save Changes</FormDialogSubmit>
      </FormDialogFooter>
    </>
  )
}

import { z } from "zod"

/** What the dialog shows for an existing user; map your API's user onto it. */
export type UserDetails = {
  id: string
  username: string
  firstName: string
  lastName: string
  email: string | null
  emailVerified: boolean
  jobTitle: string | null
  phoneNumber: string | null
  /** Whether the Users list shows the user as active; the Active switch saves it. */
  active: boolean
  /** Whether the account can sign in, if known; the form warns when it disagrees with `active`. */
  signInEnabled?: boolean
  homeFacilityId: string | null
  allowNotify: boolean
  /** Roles that only apply at the home facility, so they lose their meaning when it changes. */
  homeFacilityRoleCount: number
}

export type Facility = {
  id: string
  code: string
  name: string
}

const requiredText = (message: string) => z.string().trim().min(1, message)

export const userFormSchema = z.object({
  username: requiredText("Enter a username.").regex(
    /^\w*$/,
    "Use Latin letters, numbers and underscores only."
  ),
  email: z
    .string()
    .trim()
    .refine(
      (email) => email === "" || z.email().safeParse(email).success,
      "Enter a valid email address."
    ),
  firstName: requiredText("Enter a first name."),
  lastName: requiredText("Enter a last name."),
  jobTitle: z.string(),
  phoneNumber: z.string(),
  active: z.boolean(),
  homeFacilityId: z.string().nullable(),
  allowNotify: z.boolean(),
  removeHomeFacilityRoles: z.boolean(),
})

export type UserFormValues = z.input<typeof userFormSchema>

export const EMPTY_USER_FORM: UserFormValues = {
  username: "",
  email: "",
  firstName: "",
  lastName: "",
  jobTitle: "",
  phoneNumber: "",
  active: true,
  homeFacilityId: null,
  allowNotify: false,
  removeHomeFacilityRoles: false,
}

export function toUserFormValues(user: UserDetails): UserFormValues {
  return {
    username: user.username,
    email: user.email ?? "",
    firstName: user.firstName,
    lastName: user.lastName,
    jobTitle: user.jobTitle ?? "",
    phoneNumber: user.phoneNumber ?? "",
    active: user.active,
    homeFacilityId: user.homeFacilityId,
    allowNotify: user.allowNotify,
    removeHomeFacilityRoles: false,
  }
}

/** The list shows `active`, while sign-in follows the account; undefined when they agree or sign-in is unknown. */
export function statusMismatch({
  active,
  signInEnabled,
}: Pick<UserDetails, "active" | "signInEnabled">):
  | "listed-inactive"
  | "listed-active"
  | undefined {
  if (signInEnabled === undefined || signInEnabled === active) return undefined
  return signInEnabled ? "listed-inactive" : "listed-active"
}

/** Notifications need a verified address, and only the saved one can be verified yet. */
export function canNotify(
  email: string,
  savedEmail: string | null,
  emailVerified: boolean
) {
  return emailVerified && savedEmail !== null && email.trim() === savedEmail
}

/** The values to save: trimmed, notifications only to a verified address, and roles removed only if the facility changed. */
export function toSavedValues(
  values: UserFormValues,
  existing?: UserDetails
): UserFormValues {
  return {
    ...values,
    username: values.username.trim(),
    email: values.email.trim(),
    firstName: values.firstName.trim(),
    lastName: values.lastName.trim(),
    jobTitle: values.jobTitle.trim(),
    phoneNumber: values.phoneNumber.trim(),
    allowNotify:
      values.allowNotify &&
      existing !== undefined &&
      canNotify(values.email, existing.email, existing.emailVerified),
    removeHomeFacilityRoles:
      values.removeHomeFacilityRoles &&
      values.homeFacilityId !== (existing?.homeFacilityId ?? null),
  }
}

